  6  /**
  7   * A deliberately small, dependency-free markdown renderer for model output.
  8   *
  9   * The input is never trusted: React escapes text and attributes, and the
 10   * result is built as React nodes, so no `dangerouslySetInnerHTML` exists on
 11   * the path. Supported: headings (#..###), bullet and numbered lists,
 12   * blockquotes, fenced code blocks, inline code, bold, italic and
 13   * http(s) links. Everything else renders as plain text.
 14   */
 15  
 16  // React escapes text nodes and attributes; never pre-escape the input.
 17  
 18  type Token = { kind: "text" | "code" | "bold" | "italic" | "link"; value: string; href?: string };
 19  
 20  const INLINE_PATTERN =
 21    /(`[^`]+`)|(\*\*[^*]+\*\*)|(\*[^*\n]+\*)|(\[[^\]]+\]\((?:https?:\/\/)[^\s)]+\))/g;
 22  
 23  function tokenizeInline(escaped: string): Token[] {
 24    const tokens: Token[] = [];
 25    let lastIndex = 0;
 26    for (const match of escaped.matchAll(INLINE_PATTERN)) {
 27      const index = match.index ?? 0;
 28      if (index > lastIndex) tokens.push({ kind: "text", value: escaped.slice(lastIndex, index) });
 29      const raw = match[0];
 30      if (raw.startsWith("`")) tokens.push({ kind: "code", value: raw.slice(1, -1) });
 31      else if (raw.startsWith("**")) tokens.push({ kind: "bold", value: raw.slice(2, -2) });
 32      else if (raw.startsWith("*")) tokens.push({ kind: "italic", value: raw.slice(1, -1) });
 33      else {
 34        const label = raw.slice(1, raw.indexOf("]"));
 35        const href = raw.slice(raw.indexOf("](") + 2, -1);
 36        tokens.push({ kind: "link", value: label, href });
 37      }
 38      lastIndex = index + raw.length;
 39    }
 40    if (lastIndex < escaped.length) tokens.push({ kind: "text", value: escaped.slice(lastIndex) });
 41    return tokens;
 42  }
 43  
 44  function renderInline(escaped: string, keyPrefix: string): ReactNode[] {
 45    return tokenizeInline(escaped).map((token, index) => {
 46      const key = `${keyPrefix}-${index}`;
 47      switch (token.kind) {
 48        case "code":
 49          return <code key={key}>{token.value}</code>;
 50        case "bold":
 51          return <strong key={key}>{token.value}</strong>;
 52        case "italic":
 53          return <em key={key}>{token.value}</em>;
 54        case "link":
 55          return (
 56            <a key={key} href={token.href} target="_blank" rel="noreferrer noopener">
 57              {token.value}
 58            </a>
 59          );
 60        default:
 61          return <Fragment key={key}>{token.value}</Fragment>;
 62      }
 63    });
 64  }
