 66  /** Fenced code is rendered verbatim in a text node. */
 67  export function CodeBlock({ code }: { code: string }) {
 68    const { t } = useI18n();
 69    const [status, setStatus] = useState<"idle" | "pending" | "copied" | "failed">("idle");
 70    const generation = useRef(0);
 71    useEffect(() => {
 72      generation.current += 1;
 73      setStatus("idle");
 74      return () => { generation.current += 1; };
 75    }, [code]);
 76    async function copy() {
 77      const request = ++generation.current;
 78      setStatus("pending");
 79      try {
 80        await navigator.clipboard.writeText(code);
 81        if (request === generation.current) setStatus("copied");
 82      } catch {
 83        if (request === generation.current) setStatus("failed");
 84      }
 85    }
 86    return (
 87      <div className="md-code" style={{ contain: "inline-size", minWidth: 0, maxWidth: "100%" }}>
 88        <button type="button" className="button secondary" disabled={status === "pending"} onClick={copy}>
 89          {t(status === "pending" ? "common.loading" : status === "copied" ? "common.copied" : "common.copy")}
 90        </button>
 91        {status === "failed" && <span role="status">{t("run.copyFailed")}</span>}
 92        <pre>
 93          <code>{code}</code>
 94        </pre>
 95      </div>
 96    );
 97  }
